function getDisplayStatEntries(stats, labels) {
  return Object.entries(labels)
    .map(([key, label]) => ({ key, label, value: stats?.[key] }))
    .filter((entry) => entry.value !== null && entry.value !== undefined && entry.value !== "");
}

function formatDisplayNumber(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return "?";
  return Number.isInteger(number) ? String(number) : number.toFixed(1);
}

function getDeploymentSideLabel(side) {
  if (side === "player") return "Players";
  if (side === "enemy") return "Enemies";
  if (side === "npc") return "Scene Actors";
  return side || "Units";
}

function getDeploymentSideHeading(side) {
  if (side === "player") return "Player Side";
  if (side === "enemy") return "Enemy Side";
  if (side === "npc") return "Scene Actors";
  return getDeploymentSideLabel(side);
}

function slugifyArmyId(value, fallback = "army") {
  const slug = String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return slug || fallback;
}

function createEncounterArmyFromPreset({
  id,
  name,
  presetKey = "neutralNpc",
  preservePartyTeam = false,
}) {
  const preset = ARMY_TYPE_PRESETS[presetKey] || ARMY_TYPE_PRESETS.neutralNpc;
  const baseId = id || slugifyArmyId(name, "army");
  const partyAligned = preservePartyTeam || preset.teamId === "party" || preset.factionId === "party";
  return {
    id: baseId,
    name,
    presetKey,
    ...preset,
    teamId: partyAligned ? "party" : baseId,
    factionId: partyAligned ? "party" : baseId,
    defaultDisposition: preset.defaultDisposition || preset.disposition,
    disposition: preset.disposition || preset.defaultDisposition,
    attacksEveryone: preset.attacksEveryone === true,
    canDialogue: preset.canDialogue === true,
    nonCombatant: preset.nonCombatant === true,
    isPlayerConchampioned: preset.isPlayerConchampioned === true,
  };
}

function getRosterTutorialTarget({
  playerCount,
  enemyCount,
}) {
  const hasPlayers = playerCount > 0;
  const hasEnemies = enemyCount > 0;

  if (!hasPlayers && !hasEnemies) return "chooseParty";
  if (hasPlayers && hasEnemies) return "nextDeployment";
  if (hasPlayers && !hasEnemies) return "addEnemy";
  return "chooseParty";
}

function getRosterHint(target) {
  switch (target) {
    case "chooseParty":
      return "Choose your heroes first.";
    case "addEnemy":
      return "Now add enemies.";
    case "nextDeployment":
      return "Ready. Continue to deployment.";
    default:
      return "Build your encounter.";
  }
}

function getDeploymentTutorialTarget({
  playersPlaced,
  totalPlayers,
  enemiesPlaced,
  totalEnemies,
  playersLocked,
  enemiesLocked,
}) {
  if (totalPlayers > 0 && playersPlaced < totalPlayers) return "autoDeployPlayers";
  if (totalPlayers > 0 && !playersLocked) return "lockPlayers";
  if (totalEnemies > 0 && enemiesPlaced < totalEnemies) return "autoDeployEnemies";
  if (totalEnemies > 0 && !enemiesLocked) return "lockEnemies";
  return "continueReady";
}

function getDeploymentHint(target) {
  switch (target) {
    case "autoDeployPlayers":
      return "Deploy your player side.";
    case "lockPlayers":
      return "Lock the player side when placement looks good.";
    case "autoDeployEnemies":
      return "Now deploy the enemy side.";
    case "lockEnemies":
      return "Lock the enemy side.";
    case "continueReady":
      return "Both sides are ready.";
    default:
      return "Deploy both sides.";
  }
}

